const HeroPrincipal = () => {
    return (
    <>
        <HeroContainer>
            <Hero></Hero>
            <TituloHero>Seu site</TituloHero>
            <SubtituloHero>Para Saúde</SubtituloHero>
        </HeroContainer>
    </>
    )
}

export default HeroPrincipal;
